
// Wrapper to instantiate one custom tile for the flow to route.
// Generated by scripts/gen_custdiv.py --width 8 -- DONT edit by hand.
module custdiveg(
    // FPGA IOs (standard test IO harness)
    input wire [127:0] IN,
    output reg [127:0] OUT,
    input wire clk
);

// Test circuit IO wires
wire [7:0] A, B;
wire [7:0] O;
reg R0, R0_1;

// Assign to FPGA IO
assign A = IN[7:0];
assign B = IN[15:8];

always @(*) begin
    OUT[0] = R0_1;
    OUT[1] = R0;
    OUT[127:120] = O;
end

// Logic
custdiv #(
    .MODE_CUSTDIV(1)
) cdiv (
    .I0   (A[7:0]  ), //i
    .I1   (B[7:0]  ), //i
    .Q    (O        ), //o
    .C    (clk      ) //i
);

always @(posedge clk) begin
    R0_1 <= A[0];
    R0 <= R0_1;
end

endmodule
